INSERT INTO questions (id, chapter_id, source_tag, question_text, correct_option, summary_explanation, sort_order) VALUES (1, 1, '【診斷準則】DSM-IV 亞斯伯格症鑑別', '按照美國精神醫學會出版的精神疾病診斷標準DSM-IV，以下何者不是亞斯伯格症（Asperger’s syndrome）的鑑定標準？', 'B', 'DSM-IV中亞斯伯格症與典型自閉症的核心差異在於AS沒有顯著的語言發展遲緩與認知發展落後；但兩者皆具備社會互動障礙與侷限刻板行為。過動行為則非其診斷標準。', 1);
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (1, 'A', '缺乏社會互動', '【屬鑑定標準】DSM-IV中亞斯伯格症明確包含質的社會互動障礙（如非語言行為顯著受損、無法建立符合發展年齡的同儕關係、缺乏分享喜樂或興趣的自發行為、缺乏社交或情緒互惠）。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (1, 'B', '出現過動行為', '【本題正確解答（非鑑定標準）】過動行為屬於注意力不足過動症（ADHD）的核心特徵，並非DSM-IV亞斯伯格症的核心診斷標準項目。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (1, 'C', '沒有臨床上顯著的語言發展遲緩', '【屬鑑定標準】DSM-IV判定亞斯伯格症的重要準則之一為「沒有臨床上顯著的一般語言遲緩」（例如2歲前會使用單字、3歲前會使用溝通短句）。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (1, 'D', '過度喜歡物品的部件', '【屬鑑定標準】在「侷限、重複及刻板的行為、興趣與活動模式」中，包含對物品局部部件（parts of objects）具有持續性的執著或迷戀。');
INSERT INTO questions (id, chapter_id, source_tag, question_text, correct_option, summary_explanation, sort_order) VALUES (2, 1, '【流行病學】性別比例與群體特徵', '有關自閉症（Autism）的描述何者正確？', 'A', '自閉症盛行率男高於女（約4:1），且屬於異質性極高的光譜障礙；病因為神經生理發展異常，與父母教養或情緒剝奪完全無關。', 2);
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (2, 'A', '男生發生比例高於女生', '【本題正確解答】自閉症男女罹患比例約為 3:1 至 4:1，男童之盛行率顯著高於女童，此為歷年流行病學與學界權威研究共識。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (2, 'B', '是同質群體（homogeneous population）', '【錯誤】自閉症為異質性極高（heterogeneous population）的類群障礙，每位個案在智力、口語能力、症狀嚴重度與感覺處理上皆有極大差異。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (2, 'C', '最明顯特徵是在運算、溝通、解決問題能力的缺陷', '【錯誤】自閉症最核心且最本質的特徵是「社交溝通與社會互動缺陷」及「侷限、重複的行為模式」，而非單純運算或解決問題能力缺損。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (2, 'D', '主要的病因是來自情緒剝奪（emotional deprivation）', '【錯誤】早期精神分析學派曾提出「冰箱母親（refrigerator mother）」的情緒剝奪假說，但早已被現代醫學與腦科學徹底推翻。');
INSERT INTO questions (id, chapter_id, source_tag, question_text, correct_option, summary_explanation, sort_order) VALUES (3, 1, '【歷史與病因】Kanner 描述與生物根源', '有關自閉症（autism spectrum disorders）的敘述，何者錯誤？', 'D', '自閉症為Leo Kanner於1943年首次提出，具明確生物與遺傳根源且多為終身障礙。傳統流行病學顯示其伴隨智能障礙之比例約50%~70%，遠高於25%之說法。', 3);
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (3, 'A', 'Kanner（1943）首先描述自閉症，並認為父母的冷漠態度是致病因素', '【正確敘述】Leo Kanner 在1943年發表《Autistic disturbances of affective contact》，首度將自閉症自精神分裂中區分出來，且其早期曾推論父母之知性冷漠可能為誘因。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (3, 'B', '研究指出自閉症的發生有其生物性根源（biological roots）', '【正確敘述】現代神經影像學、分子遺傳學與神經發育生物學均充分證實自閉症具有多基因遺傳及神經迴路異常之生物性根源。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (3, 'C', '95%以上的自閉症是終身的問題，不會痊癒為正常', '【正確敘述】自閉症為廣泛性神經發展障礙，特質與神經型態伴隨終身，雖能透過早療顯著提升適應生活能力，但95%以上個案無法「完全痊癒」成為典型發展個案。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (3, 'D', '約25%的自閉症兒童伴隨有智能障礙', '【本題正確解答（錯誤敘述）】在傳統臨床診斷文獻與權威教材中，自閉症兒童約有 50%～70% 伴隨智能障礙（近年隨輕度/高功能納入ASD診斷，伴隨智障比例約佔30%~50%），但絕非低至25%，因此選項敘述比例錯誤。');
INSERT INTO questions (id, chapter_id, source_tag, question_text, correct_option, summary_explanation, sort_order) VALUES (4, 1, '【診斷演進】DSM-IV 亞斯伯格症歷史', '有關亞斯伯格症（Asperger’s syndrome, AS）的診斷標準，何者錯誤？', 'B', 'DSM-IV（1994）已正式將亞斯伯格症納入診斷手冊中；其診斷具備社交互動困難與侷限刻板行為，但無顯著語言及認知發展落後。', 4);
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (4, 'A', '智力及語言發展沒有明顯落後', '【正確敘述】依DSM-IV準則，亞斯伯格症個案在認知智力表現及早期語言里程碑上無臨床顯著落後。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (4, 'B', 'DSM-IV中，尚未正式列出AS的診斷標準', '【本題正確解答（錯誤敘述）】美國精神醫學會早於 1994 年出版之 DSM-IV 中，已正式將「亞斯伯格疾患（Asperger Disorder）」獨立列為廣泛性發展障礙（PDD）之一。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (4, 'C', '有社交互動的困難', '【正確敘述】AS個案具備質的社會互動障礙（如無法理解非語言社交線索、缺乏社會情緒互惠性）。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (4, 'D', '偏好某些行為、興趣或活動模式', '【正確敘述】具有侷限、重複且強烈刻板的特殊興趣或固著儀式行為。');
INSERT INTO questions (id, chapter_id, source_tag, question_text, correct_option, summary_explanation, sort_order) VALUES (5, 1, '【臨床鑑別】個案行為特徵與 ADHD 鑑別', '在語言評估時，語言治療師發現8歲的祥祥有下列的語言及行為表現：①在治療室中一再跑跳、爬上爬下 ②尚未聽完指令說明就先行動 ③話說個不停但內容空洞、敘事情節雜亂無章 ④無法專注並完成有結構性或有訂定目標的活動 ⑤不會依溝通對象或情境的不同而調整說話方式及內容。 你認為祥祥最可能是以下那一類型的個案？', 'A', '祥祥的行為符合過動、衝動與注意力分散的三大ADHD特徵，言語上的滔滔不絕與語用問題亦常次發於ADHD執行功能缺陷。', 5);
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (5, 'A', '注意力不足過動缺陷症（attention deficit/hyperactivity disorder, ADHD）', '【本題正確解答】祥祥表現出典型ADHD三大核心範疇：過動（跑跳爬）、衝動控制不良（未聽完指令就行動、插嘴滔滔不絕）與注意力缺乏（無法專注完成活動），伴隨因執行功能不足引起的言談組織雜亂與語用調節困難。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (5, 'B', '亞斯伯格症（Asperger’s syndrome）', '【錯誤】亞斯伯格症個案之主要特徵在於特殊主題的固著深入探索與社交心智理論困難，題幹中顯著的衝動性肢體過動非AS首要鑑別徵候。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (5, 'C', '聽覺處理異常（auditory processing disorder）', '【錯誤】APD主要表現在背景噪音下的聽語理解困難或聲音定位困難，不直接引起肢體跑跳與衝動過動。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (5, 'D', '泛自閉症障礙（autism spectrum disorder）', '【錯誤】題幹描述主要反映注意力控制缺陷、抑制控制失敗（衝動性）與運動過動，診斷首選為 ADHD。');
INSERT INTO questions (id, chapter_id, source_tag, question_text, correct_option, summary_explanation, sort_order) VALUES (6, 1, '【認知與語言】亞斯伯格症鑑定指標', '以下何者是亞斯伯格症（Asperger syndrome）兒童的鑑定標準之一？', 'C', '亞斯伯格症兒童具備社交互動困難與刻板興趣，但在早期認知與一般語言里程碑發展上沒有臨床顯著之遲緩。', 6);
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (6, 'A', '沒有明顯的社會互動能力缺陷', '【錯誤】社會互動能力的質性缺損是亞斯伯格症的必要核心診斷要件之一。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (6, 'B', '有注意力缺陷或過動行為', '【錯誤】注意力缺陷與過動並非亞斯伯格症之法定核心診斷指標。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (6, 'C', '沒有臨床上顯著的語言或認知發展遲緩', '【本題正確解答】依DSM-IV準則，亞斯伯格症在2歲前具備單字溝通、3歲前具備片語，且認知能力與自理能力在正常發展範圍內。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (6, 'D', '非語文智力優於語文智力', '【錯誤】臨床測驗顯示，亞斯伯格症兒童通常語文智商（VIQ）多數等於或顯著優於操作非語文智商（PIQ），並非「非語文優於語文」。');
INSERT INTO questions (id, chapter_id, source_tag, question_text, correct_option, summary_explanation, sort_order) VALUES (7, 1, '【語用與鑑別】發展性語言障礙 (DLD) vs ASD', '關於發展性語言障礙（DLD）兒童的敘述，下列何者錯誤？', 'C', 'DLD兒童的語用限制多源自語言工具本身（結構、詞彙）的不足；而自閉症（ASD）兒童的語用缺損則是深層的心智理論與社交互動動機異常，兩者不可混為一談。', 7);
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (7, 'A', '發展性語言障礙兒童通常會伴隨出現讀寫學習問題，且這些學習問題不會隨著年齡增長而消失', '【正確敘述】DLD（舊稱SLI）兒童在進入學齡期後常延伸為閱讀理解與文字書寫障礙，多數個案之學習問題會持續至青少年期與成年期。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (7, 'B', '發展性語言障礙是指個案出現明顯的語言問題，但沒有明確的生理因素造成', '【正確敘述】DLD診斷原則在於排除腦傷、聽障、全般性智障或嚴重神經生理病變，其語言落後找不到明確單一生理病因。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (7, 'C', '發展性語言障礙兒童出現的語用問題和自閉症兒童類似', '【本題正確解答（錯誤敘述）】兩者語用本質截然不同：ASD之語用缺損源自根本性的社會溝通動機缺乏、共同注意力（joint attention）缺乏與心智理論（ToM）受損；DLD的語用問題通常是次發於語言形式（文法、字彙）理解與表達能力不足，非社交情緒互惠的本質喪失。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (7, 'D', '發展性語言障礙兒童早期的語言發展歷程跟正常兒童相似，但速度較慢', '【正確敘述】DLD在語法與構詞習得的順序上大多依循正常兒童的發展歷程，但速度大幅延緩且落差拉大。');
INSERT INTO questions (id, chapter_id, source_tag, question_text, correct_option, summary_explanation, sort_order) VALUES (8, 1, '【診斷手冊演進】DSM-5 vs DSM-IV 差異', '關於自閉症類群障礙（Autism spectrum disorder, ASD）的鑑別診斷，DSM-5與DSM-IV的差異為何？', 'B', 'DSM-5由三合一向度改為二合一向度，將『口語發展遲緩』排除在ASD必要核心診斷之外（改列為臨床註記），突顯ASD的本質是社交溝通與侷限行為，而非口語語法發展本身。', 8);
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (8, 'A', '排除社交溝通缺陷', '【錯誤】DSM-5依舊將「社交溝通與社會互動缺陷」列為最重要的第一大核心領域。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (8, 'B', '排除口語語言溝通缺陷', '【本題正確解答】DSM-IV原本將「口語溝通障礙（如口語遲緩或完全缺乏）」列為自閉症核心三大領域之一；但DSM-5考量許多ASD個案（如原亞斯伯格）無口語遲緩，因而將『口語語言發展遲緩』從核心診斷要件中排除，改列為附加之規格註記（specifier：with or without accompanying language impairment）。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (8, 'C', '排除侷限及重複行為', '【錯誤】DSM-5依然保留第二大核心領域為「侷限、重複的行為、興趣或活動模式」，並新增了感覺處理異常維度。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (8, 'D', '排除固著性的興趣與行為', '【錯誤】固著行為與刻板興趣在DSM-5中依舊是不可或缺之診斷要件。');
INSERT INTO questions (id, chapter_id, source_tag, question_text, correct_option, summary_explanation, sort_order) VALUES (9, 1, '【病因機轉】基因、腦神經與迷思釐清', '有關自閉症（ASD）的原因，下列敘述何者錯誤？', 'D', '自閉症的成因高度關聯多基因遺傳與大腦神經發展（如杏仁核、邊緣系統），與疫苗注射或父母親之教養方式完全無關。', 9);
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (9, 'A', '可能是很多不同基因導致', '【正確敘述】全基因體定序（GWAS）證實自閉症具有高度多基因遺傳結構，涉及數百個基因變異之交互作用。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (9, 'B', '有研究顯示腦區中的杏仁核有異常', '【正確敘述】神經解剖學與功能性MRI發現ASD個案的杏仁核（Amygdala，負責社交情緒解讀）在神經元密度、發育體積與功能連結上均存在顯著異常。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (9, 'C', '和注射預防疫苗無關', '【正確敘述】國際眾多大規模實證醫學長期追蹤已徹底證實：MMR等任何常規疫苗注射與自閉症之發生完全無關。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (9, 'D', '和父母親教養有關', '【本題正確解答（錯誤敘述）】自閉症是先天的神經系統發育障礙，與父母親之教養風格或關愛程度毫無因果關係。將自閉症怪罪於教養是過時且錯誤的觀念。');
INSERT INTO questions (id, chapter_id, source_tag, question_text, correct_option, summary_explanation, sort_order) VALUES (10, 1, '【臨床行為與認知】仿說功能與認知優勢', '關於自閉症（ASD）兒童的敘述，下列何者錯誤？', 'B', '自閉症兒童的鸚鵡式仿說（Echolalia）常具有積極的溝通功能與調節意圖，語言治療師應把握其仿說作為擴展真實溝通的介入橋樑，而非單純將其視為異常行為加以消弱。', 10);
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (10, 'A', '50％～70％ASD兒童的非口語智力測驗標準分數低於70', '【正確敘述】傳統流行病學統計與臨床文獻顯示，約半數至七成ASD兒童之非口語認知表現落在低於平均兩個標準差（標準分數<70，達輕度智障以上標準）。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (10, 'B', 'ASD兒童的鸚鵡式仿說（echolalia）是一種異常行為，不具溝通功能', '【本題正確解答（錯誤敘述）】現代語言病理學研究證實，ASD兒童的立即性或延宕性仿說具有豐富的溝通意圖與功能（如：確認訊息、請求、抗議、輪替回應、自我安撫與語音處理過渡策略），絕非『不具溝通功能的無效異常行為』。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (10, 'C', 'ASD兒童常出現固著或重複的話語、動作或是物品使用', '【正確敘述】固著重複的語言（重複腳本台詞）、動作刻板（拍翅、搖擺）或排列物品為ASD的核心症狀表現。');
INSERT INTO question_options (question_id, option_key, option_text, explanation) VALUES (10, 'D', 'ASD兒童的區辨和短期記憶力為其優勢能力', '【正確敘述】弱中央聚合（weak central coherence）理論指出，ASD個案常具備突出的局部視覺區辨力、細節捕捉力與機械性短期記憶之認知優勢。');