UPDATE chapters SET title = '第一節 自閉症兒童的診斷以及臨床表現', subtitle = '自閉症核心診斷標準與臨床表現檢測', description = '本章節針對自閉症（ASD）與亞斯伯格症（AS）之診斷標準演進（DSM-IV 至 DSM-5）、流行病學、致病成因、神經生理機轉及臨床行為特徵進行核心觀念檢測，每題均附選項逐項深入解析。' WHERE id = 1;
